// TH14 v1.00b Stage 3 midboss nonspell 1: st03mbs.ecl MBoss1 (src 52-85)
// with MBoss1_at (src 87-135). Entry state from MBoss (src 8-50): boss already
// at (0,128), hurtbox/hitbox 48 -> radius 24, life 11000, position limit
// (0,128,280,64), body collision on.
//
// Synthetic training shell: no DPS, no drops, presentation/dialogue omitted.
// Source shared-slot ownership for this card: int3 = completed moveRand steps,
// fx6/fx7 = moveRand logical unit vector. Source F0/I0 stay task locals here.

const TIME_LIMIT: int = 2284;
const OPENING_BUFFER: int = 120;

const TH14_BIG_BALL: int = 640;
const TH14_BALL2: int = 432;

// Source MBoss1_at etEx chain, physical part only:
//   WAIT 10 -> ANGLE_ACCEL(a=50, speed += 0.035/frame, angle += F0/frame)
//   -> SHOOT then parent delete.  ANIM/BRIGHT/PLAYSOUND/SPEEDUP are omitted.
xformdef PARENT_CURVE(omega: angle) {
    wait(10);
    set_ang_vel(omega);
    @50 set_accel(0.035fx);
    set_ang_vel(0deg);
    set_accel(0fx);
    set_life(1);
}

// Source SHOOTPREP: aim mode 8 (random angle and speed, TH18 shared table).
// r=-999 -> current parent angle; m=-999 -> keep parent speed; s=delta,
// n=1.5 speed amplitude. Counts/deltas follow the source difficulty stack.
async sub parent_burst() {
    var rank: int = global(GVAR_RANK);
    var cnt: int = 1;
    var delta: int = 910; // 5 deg
    if rank == RANK_NORMAL { cnt = 3; }
    if rank == RANK_HARD { cnt = 5; delta = 1820; }   // 10 deg
    if rank == RANK_LUNATIC { cnt = 5; delta = 2731; } // 15 deg
    // Parent curve has 10+50 frames of EX schedule and the task runs one frame late.
    wait(59);
    var px: fx = $self_x;
    var py: fx = $self_y;
    var ang0: angle = $self_angle;
    var spd0: fx = $self_speed;
    for k in 0..cnt {
        var ra: int = rand(65536);
        var ua: fx = (ra - 32768) as fx / 32768;
        var off: int = (ua * (delta as fx)) as int;
        var a: angle = ang0 + (off as angle);
        var rv: int = rand(65536);
        var us: fx = (rv - 32768) as fx / 65536 + 0.5fx;
        _ = fire(TH14_BALL2, 2, px, py, spd0 + us * 1.5fx, a, none, none);
    }
}

// --- moveRand(60,4,0.4) recipe with moveLimit(0,128,280,64) -----------------
// Bounds: position x in [-140,140], y in [96,160]; direction inner zone
// x +/-70, y 112..144. Speed is 0.4*(1-k/60); the mode parameter does not
// override the speed interpolation slot.
sub arm_next_step() {
    var k: int = self_int(3) + 1;
    set_self_int(3, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.4fx * ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(6) * speed;
    var ny: fx = $self_y + self_fx(7) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    // phase 5 integrates after ECL, so this arms the next source movement tick
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(6, cos(a));
    set_self_fx(7, sin(a));
    set_self_int(3, 0);
    arm_next_step();
}

sub move_rand() {
    // Source signed unit random * pi; values are unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source +/-pi/2 guard, epsilon 0.05 rad.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

sub advance(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// --- MBoss1_at: fixed-direction ring of stopped big balls --------------------
// etSprite type18/color1, aim mode 3, angle pi/2, count 24 (E/N/H) or 30 (L),
// one layer, final etSpeed(0,0), etDist 16. The single-layer spread is unused.
sub volley(turn: angle, ways: int) {
    sh_reset(0);
    sh_sprite(0, TH14_BIG_BALL, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_angle(0, 90deg, 0deg);
    sh_count(0, ways, 1);
    sh_speed(0, 0fx, 0fx);
    sh_dist(0, 16fx);
    sh_xform(0, PARENT_CURVE(turn));
    sh_task(0, parent_burst);
    sh_fire(0);
}

async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // Entry is stationary at (0,128); source F0 = 0.017453 rad/frame = 1 deg/frame.
    set_self_int(3, 60);
    set_self_fx(6, 1fx);
    set_self_fx(7, 0fx);
    var rank: int = global(GVAR_RANK);
    var ways: int = 24;
    var pairs: int = 8;
    var gap: int = 80;
    var tail: int = 30;
    if rank == RANK_LUNATIC {
        ways = 30;
        pairs = 10;
        gap = 20;
        tail = 0;
    }
    var omega: int = 182;

    // Source schedule per pair: wait 60 -> at(); wait 30 -> F0*=-1 -> at();
    // wait 80/20 -> moveRand(60,4,0.4); wait 70.  Source interrupt 1800 stops
    // emission; the final pair is cut at 1800 for E/N/H.
    for cycle in 0..pairs {
        advance(60);
        volley(omega as angle, ways);
        advance(30);
        omega = 0 - omega;
        volley(omega as angle, ways);
        if cycle + 1 < pairs || rank == RANK_LUNATIC {
            advance(gap);
            move_rand();
            advance(70);
        }
    }
    advance(tail);
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 11000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
